// Secure card creation with textContent for data, template for structure
function createCardSecure(lesson, completed) {
 let status = getStatus(lesson.id, completed);
 let isLocked = status === 'locked';
 let badge = status === 'completed'? 'Completed' : status === 'current'? 'Current' : 'Locked';
 let button = isLocked? 'Locked' : status === 'completed'? 'Review' : 'Start Lesson';

