 badge,
 button,
 dataset: { lesson: lesson.id },
 classList: { contains: (c) => c === 'start-btn' },
 onClick: () => {
 if (!isLocked) {
 console.log(`→ Navigating to lesson.html?course=${COURSE_ID}&lesson=${lesson.id}`);
 }
 }
 };
 return card;
