// Efficient render with grid 1 reflow
function renderLessons(lessons, completed) {
 console.log(`\n--- Rendering ${lessons.length} lessons (efficient 1 reflow) ---`);
 let grid = { children: [], appendChild: function(c) { this.children.push(c); } };
 lessons.forEach(lesson => {
 let card = createCardSecure(lesson, completed);
 let icon = card.status === 'completed'? '✅' : card.status === 'current'? '▶' : '🔒';
 console.log(`${icon} ${lesson.id}. ${lesson.title} - ${card.status.toUpperCase()} - [${card.button}]`);
 grid.appendChild(card); // Memory no reflow
 });
 console.log(`Appended grid with ${grid.children.length} cards to container - 1 reflow efficient`);
 return grid;
}

// Event delegation - one listener
function setupDelegation(grid) {
 console.log('\n--- Event Delegation - One Listener for All Buttons ---');
 grid.addEventListener = (event, callback) => {
 console.log(`Added ${event} listener to grid parent - delegation`);
 grid.callback = callback;
 };

 grid.addEventListener('click', (event) => {
 // Modern: optional chaining and dataset
 let lessonId = event.target?.dataset?.lesson;
 if (lessonId && event.target.classList.contains('start-btn')) {
 console.log(`\nDelegated click: Lesson ${lessonId}`);
 handleLessonClick(Number(lessonId));
 }
 });
}

function handleLessonClick(lessonId) {
 let status = getStatus(lessonId, completed);
 if (status === 'locked') {
 console.log(`🔒 Locked! Need ${completed + 1} first`);
 return;
 }
 if (status === 'completed') {
 console.log(`✅ Reviewing lesson ${lessonId}`);
 return;
 }

 // Modern: Spread immutable updates
 let newLessons = lessons.map(l => {
 if (l.id === lessonId) return {...l, status: 'completed', xp: 100, coins: 10};
 if (l.id === lessonId + 1) return {...l, status: 'current'};
 return l;
 });

 let newUser = {...firebaseData, xp: xp + 100, coins: coins + 10, completed: completed + 1};
 xp = newUser.xp;
 coins = newUser.coins;
 completed = newUser.completed;
 lessons = newLessons;

 let percent = calculateProgress(completed, TOTAL_LESSONS);
 console.log(`🎉 Completed! XP: ${xp}, Coins: ${coins}, Progress: ${percent}%`);
 renderLessons(lessons, completed);
}

// Async load simulation
async function loadData() {
 console.log('\n--- Async/Await Loading ---');
 await new Promise(r => setTimeout(r, 50));
 console.log('Data loaded from Firebase');
 return { xp, coins, completed };
}

// Main flow
loadData().then(data => {
 console.log(`\nLoaded: XP=${data.xp}, Completed=${data.completed}`);
 let grid = renderLessons(lessons, completed);
 setupDelegation(grid);

 console.log('\n--- Simulating Clicks ---');
 // Simulate click via delegation
 grid.callback({ target: { dataset: { lesson: 3 }, classList: { contains: (c) => c === 'start-btn' } } });

 console.log('\n--- Modern Methods ---');
 let titles = lessons.map(l => l.title);
 console.log(`Titles (map): ${titles.slice(0, 3).join(', ')}...`);
 console.log(`Completed (filter): ${lessons.filter(l => l.status === 'completed').map(l => l.title).join(', ')}`);
 console.log(`Current (find): ${lessons.find(l => l.status === 'current')?.title?? 'None'}`);
 console.log(`Total XP (reduce): ${lessons.reduce((t, l) => t + l.xp, 0)}`);
 console.log(`Has locked? (some): ${lessons.some(l => l.status === 'locked')}`);

 // Destructuring final state
 let { xp: finalXP, coins: finalCoins, completed: finalCompleted } = { xp, coins, completed };
 console.log(`\n=== FINAL with Modern JS ===`);
 console.log(`XP: ${finalXP}, Coins: ${finalCoins}, Completed: ${finalCompleted}/${TOTAL_LESSONS} - ${calculateProgress(finalCompleted)}%`);
 console.log(`All modern: Template literals, Destructuring, Spread, Arrow,?.,??, Async/Await, Delegation, map/filter/find/reduce`);
});
